import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    var counter = 0
    var S: String? = null
    var T: String? = null

    while (scanner.hasNextLine()) {
        val d = scanner.nextLine()
        if (counter == 0) {
            S = d
        } else {
            T = d
            var ans = "YES"
            var j = 0
            for (i in T!!.lastIndex downTo 0) {
                if (T[i] != S!![j]) {
                    ans = "NO"
                    break
                }
                j++
            }
            println(ans)
        }
        counter++
    }
}
